import React, { useState, useEffect } from "react";
import { Input, Row, Form, Card, Col, Button, message, Select } from "antd";
import Flex from "components/shared-components/Flex";
import { useNavigate, useLocation } from "react-router-dom";
import DiscardButton from "components/shared-components/Buttons/DiscardButton";
import {
  fetchAllFaqs,
  addFaq,
  editFaq,
  setModalVisible,
} from "store/slices/faqSlice";
import { useDispatch, useSelector } from "react-redux";
import { filterOption } from "components/util-components/FormItems/dropDownSearch";
import { APP_PREFIX_PATH } from "configs/AppConfig";
import CreateSectionModal from "../components/faqSectionModal";

const FaqFormFields = ({ mode }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { Option } = Select;
  const dispatch = useDispatch();
  const [form] = Form.useForm();
  const [questions, setQuestions] = useState([{ question: "", reply: "" }]);

  const { submitting, error, loading, faqSections } = useSelector(
    (state) => state.faqs
  );

  useEffect(() => {
    dispatch(fetchAllFaqs());
  }, [dispatch]);

  // Pre-populate form if in edit mode
  useEffect(() => {
    console.log(location.state, "THIS IS STATE LOCATION");
    console.log(mode, "THIS IS MODE");

    if (mode === "EDIT") {
      const { sectionId, questionId, question, answer } = location.state;
      console.log(sectionId, "THIS IS SECTIONID");
      console.log(question, "THIS IS QUESTION");
      console.log(answer, "THIS IS ANSWER");

      form.setFieldsValue({
        category: sectionId,
      });
      setQuestions([{ question, reply: answer }]);
    }
  }, [mode, location.state, form]);

  const handleAddQuestion = () => {
    setQuestions([...questions, { question: "", reply: "" }]);
  };

  const handleQuestionChange = (index, field, value) => {
    const newQuestions = [...questions];
    newQuestions[index][field] = value;
    setQuestions(newQuestions);
  };

  const handleRemoveQuestion = (index) => {
    const newQuestions = questions.filter((_, i) => i !== index);
    setQuestions(newQuestions);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();

      if (questions.some((q) => !q.question || !q.reply)) {
        message.error("Please fill in all questions and replies");
        return;
      }

      if (mode === "ADD") {
        await dispatch(
          addFaq({
            category: values.category,
            questions,
          })
        ).unwrap();
        message.success("FAQ added successfully");
      } else if (mode === "EDIT") {
        const { sectionId, questionId } = location.state;
        await dispatch(
          editFaq({
            sectionId,
            questionId,
            updatedQuestion: questions[0].question,
            updatedAnswer: questions[0].reply,
          })
        ).unwrap();
        message.success("FAQ updated successfully");
      }

      form.resetFields();
      setQuestions([{ question: "", reply: "" }]);
      navigate(`${APP_PREFIX_PATH}/app/management/layout/faq/list`);
      dispatch(fetchAllFaqs());
    } catch (error) {
      if (error.errorFields) {
        message.error("Please fill in all required fields");
      }
    }
  };

  return (
    <Row gutter={16}>
      <Col xs={24} sm={24} md={17}>
        <Form
          form={form}
          layout="vertical"
          name="faq_form"
          className="ant-advanced-search-form"
        >
          <Card title={mode === "ADD" ? "Add FAQ's" : "Edit FAQ"}>
            <Row gutter={16} align="middle">
              <Col flex="auto">
                <Form.Item
                  name="category"
                  label="Section"
                  rules={[
                    { required: true, message: "Please select a section!" },
                  ]}
                >
                  <Select
                    className="w-100"
                    placeholder="Choose a Section"
                    showSearch
                    filterOption={filterOption}
                    loading={loading}
                  >
                    {faqSections && faqSections.length > 0 ? (
                      faqSections.map((section) => (
                        <Option key={section} value={section}>
                          {section}
                        </Option>
                      ))
                    ) : (
                      <Option disabled>No sections available</Option>
                    )}
                  </Select>
                </Form.Item>
              </Col>
              <Col>
                <Button
                  type="primary"
                  style={{ marginTop: 10 }}
                  onClick={() => dispatch(setModalVisible(true))}
                >
                  Create Section
                </Button>
              </Col>
            </Row>

            {questions.map((question, index) => (
              <div key={index} className="mb-4">
                <Form.Item
                  label={`Question ${index + 1}`}
                  rules={[
                    { required: true, message: "Please input question!" },
                  ]}
                >
                  <Input
                    placeholder="Enter FAQ Question"
                    value={question.question}
                    onChange={(e) =>
                      handleQuestionChange(index, "question", e.target.value)
                    }
                  />
                </Form.Item>

                <Form.Item
                  label={`Reply ${index + 1}`}
                  rules={[{ required: true, message: "Please input reply!" }]}
                >
                  <Input.TextArea
                    rows={4}
                    placeholder="Enter your reply"
                    value={question.reply}
                    onChange={(e) =>
                      handleQuestionChange(index, "reply", e.target.value)
                    }
                  />
                </Form.Item>

                {questions.length > 1 && (
                  <Button
                    type="primary"
                    danger
                    onClick={() => handleRemoveQuestion(index)}
                  >
                    Remove
                  </Button>
                )}
              </div>
            ))}

            <Button
              type="dashed"
              onClick={handleAddQuestion}
              style={{ width: "100%", marginBottom: 16 }}
            >
              Add Question
            </Button>
          </Card>

          <Flex
            className="py-2"
            mobileFlex={false}
            justifyContent="space-between"
          >
            <DiscardButton form={form} />
            <Button
              type="primary"
              onClick={handleSubmit}
              loading={submitting}
              disabled={submitting}
            >
              {submitting ? "Submitting..." : mode === "ADD" ? "Add" : "Save"}
            </Button>
          </Flex>
        </Form>
        <CreateSectionModal />
      </Col>
    </Row>
  );
};

export default FaqFormFields;
